-- 池袋店のおちゃのこCSV 2ファイル（合計6,356件）から確認した採番規則と既存コードを保存する。
CREATE TABLE IF NOT EXISTS product_code_rules (
  title_key text PRIMARY KEY REFERENCES product_name_templates(title_key) ON DELETE CASCADE,
  display_name text NOT NULL,
  base_expression text NOT NULL,
  branch_width integer NOT NULL DEFAULT 2,
  damage_suffix text,
  special_policy text,
  source_note text,
  analyzed_rows integer NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS product_code_sequences (
  title_key text NOT NULL REFERENCES product_code_rules(title_key) ON DELETE CASCADE,
  base_code text NOT NULL,
  last_branch integer NOT NULL CHECK (last_branch >= 0),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(title_key, base_code)
);

CREATE TABLE IF NOT EXISTS legacy_product_codes (
  product_code text PRIMARY KEY,
  source_name text NOT NULL,
  imported_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO product_code_rules(title_key,display_name,base_expression,branch_width,damage_suffix,special_policy,source_note,analyzed_rows)
VALUES(
  'onepiece',
  'ワンピースカード（池袋店既存ルール）',
  'カード型番からハイフンを除去',
  2,
  'dmg',
  'ドンカード・サプライ・デッキ商品等は通常カードと別の専用連番',
  'products1 (1).csv と products2.csv／商品番号155～7764／2026-08-15解析',
  6356
)
ON CONFLICT(title_key) DO UPDATE SET
  display_name=EXCLUDED.display_name,
  base_expression=EXCLUDED.base_expression,
  branch_width=EXCLUDED.branch_width,
  damage_suffix=EXCLUDED.damage_suffix,
  special_policy=EXCLUDED.special_policy,
  source_note=EXCLUDED.source_note,
  analyzed_rows=EXCLUDED.analyzed_rows,
  updated_at=now();

